          "before": "import Benitoite.Unofficial.Json.Codec as Codec\nimport Benitoite.Unofficial.Json as Json\nimport Benitoite.Unofficial.Test.Property as Property\nimport Benitoite.Unofficial.IO.Random\n\nimplement Trait.Show[Address]\n  function show(x: Address) -> String\n    return \"Address(\" + \"city: \" + Trait.Show.show(Address.city(x)) + \")\"\n  end function\nend implement\n\nimplement Trait.Order[Address]\n  function compare(x: Address, y: Address) -> Trait.Ordering\n    bind deriveOrder0 <- Trait.Order.compare(x: Address.city(x), y: Address.city(y))\n    match deriveOrder0 with\n      case Trait.Ordering.Equal -> ()\n      case other -> return other\n    end match\n    return Trait.Ordering.Equal\n  end function\nend implement\n\n/// Encodes Address in declaration order, returning the first relative conversion failure.\npublic function encodeAddress(value: Address) -> Result[Json.Value, Codec.ConversionError]\n  bind deriveField0 <- try Result.mapError(r: (Codec.encodeString)(Address.city(value)), f: lambda(error) return Codec.prepend(part: Codec.PathPart.Field(\"city\"), error: error) end lambda)\n  return Result.Ok(Json.Value.Object(Map.fromList([Pair(\"city\", deriveField0)])))\nend function\n\n/// Decodes Address in declaration order, then rejects the first extra key.\npublic function decodeAddress(value: Json.Value) -> Result[Address, Codec.ConversionError]\n  bind deriveMembers <- try Codec.decodeObject(value)\n  bind deriveField0 <- try Codec.decodeField(members: deriveMembers, key: \"city\", decode: Codec.decodeString, decodeMissing: Codec.missing)\n  bind _ <- try Codec.rejectExtra(members: deriveMembers, keys: [\"city\"])\n  return Result.Ok(Address(city: deriveField0))\nend function\n\nfunction derive_shrinkAddress_0(original: Address, value: String) -> Address\n  return Address(..original, city: value)\nend function\n\nfunction derive_shrinkAddress_steps_0(value: Address) -> Property.ShrinkStep[Address]\n  return Property.ShrinkStep.Skip(lambda()\n    bind candidates <- Property.Shrinker.candidates(Property.shrinkString())\n    return Property.appendSteps(left: Property.mapSteps(steps: candidates(Address.city(value)), f: derive_shrinkAddress_0(original: value, value: _)), right: lambda() return Property.ShrinkStep.Done end lambda)\n  end lambda)\nend function\n\n/// Generates Address in field order with the same size and successive random states.\npublic function genAddress() -> Property.Gen[Address]\n  bind deriveRun0 <- Property.Gen.run(Property.string())\n  return Property.Gen(run: lambda(generator: Random.Generator, size: Integer)\n    bind derivePair0 <- deriveRun0(generator: generator, size: size)\n    return Pair(Address(city: Pair.first(derivePair0)), Pair.second(derivePair0))\n  end lambda)\nend function\n\n/// Shrinks one field at a time in declaration order; cross-field conditions require a custom shrinker.\npublic function shrinkAddress() -> Property.Shrinker[Address]\n  return Property.Shrinker(candidates: lambda(value: Address)\n    return derive_shrinkAddress_steps_0(value)\n  end lambda)\nend function\n",
