          "before": "",
          "after": "// benitoite-derive:begin traits\nimport Benitoite.Trait as Trait\n\nimplement Trait.Show[Person]\n  function show(x: Person) -> String\n    return \"Person(\" + \"name: \" + Trait.Show.show(Person.name(x)) + \", age: \" + Trait.Show.show(Person.age(x)) + \")\"\n  end function\nend implement\n\nimplement Trait.Order[Person]\n  function compare(x: Person, y: Person) -> Trait.Ordering\n    bind deriveOrder0 <- Trait.Order.compare(x: Person.name(x), y: Person.name(y))\n    match deriveOrder0 with\n      case Trait.Ordering.Equal -> ()\n      case other -> return other\n    end match\n    bind deriveOrder1 <- Trait.Order.compare(x: Person.age(x), y: Person.age(y))\n    match deriveOrder1 with\n      case Trait.Ordering.Equal -> ()\n      case other -> return other\n    end match\n    return Trait.Ordering.Equal\n  end function\nend implement\n// benitoite-derive:end traits\n"
        }
      ]
