from harness import *
doc=(I/'docs.bnt').read_text()
missing=doc.replace('/// ```diagnostic\n/// E0401\n/// ```\n','')
run('doc missing expected',[CLI,'test','--doc',write('doc-missing.bnt',missing)],expected=2,contains=['E0260'])
run('doc expectation mismatch',[CLI,'test','--doc',write('doc-mismatch.bnt',doc.replace('/// E0401','/// E0402'))],expected=1,contains=['FAILED'])
# ///コメントのUnicodeの列を元のバイト位置と照合する。
unicode=doc.replace('"wrong"','"誤り"')
r=json.loads(run('doc Unicode location',[CLI,'test','--doc','--check','--report=json',write('doc-unicode.bnt',unicode)]).stdout)
d=r['targets'][0]['docExamples'][1]['observedDiagnostics'][0]['primary'];print('Unicode position',d)
assert d['start']['line']==9 and d['start']['column']==14
assert unicode.encode()[d['start']['offset']:d['end']['offset']]=='"誤り"'.encode()
# 元ファイルのprivate宣言は例へ暗黙には移さない。
private='''/// ```benitoite check
/// function example() -> Integer
///   return secret()
/// end function
/// ```
function secret() -> Integer
 return 7
end function
'''
run('doc private boundary',[CLI,'test','--doc','--check',write('doc-private.bnt',private)],expected=2,contains=['E0301'])
opaque='''/// ```benitoite check
/// import Positive
/// function example() -> Positive.Positive
///   return Positive.Positive(raw: -1)
/// end function
/// ```
public function documented() -> Unit
 return ()
end function
'''
run('doc opaque boundary',[CLI,'test','--doc','--check',write('doc-opaque.bnt',opaque)],expected=2,contains=['E0340'])
# Assert.failがcheck時に実行されないことも実出力で区別する。
falseDoc=doc.replace('expected: 2','expected: 99')
run('doc check skips Assert',[CLI,'test','--doc','--check',write('doc-false.bnt',falseDoc)])
run('doc executes Assert',[CLI,'test','--doc',I/'doc-false.bnt'],expected=1,contains=['FAILED'])
# 四モード・通常テスト・複数@testを含む例の件数を一つの報告で照合する。
extra='''
/// ```benitoite check
/// function checked() -> Unit uses State
///   bind _ <- Reference.new(1)
///   return ()
/// end function
/// ```
/// ```benitoite
/// import Benitoite.IO.Console
/// function main() -> Unit uses Console.Write
///   Console.writeLine("ready")
/// end function
/// ```
/// ```output
/// ready
/// ```
public function extra() -> Unit
 return ()
end function
@test
function ordinary() -> Unit uses Assert.Check
 Assert.equal(actual: 1, expected: 1)
end function
'''
multi=doc.replace('/// ```\n/// ```benitoite error', '/// @test\n/// function second() -> Unit uses Assert.Check\n///   Assert.equal(actual: 1, expected: 1)\n/// end function\n/// ```\n/// ```benitoite error')+extra
p=write('doc-four.bnt',multi)
r=json.loads(run('doc four report',[CLI,'test','--doc','--check','--report=json',p]).stdout)
assert r['aggregateEffects']['expanded']==['Assert.Check','Console.Write']
t=r['targets'][0];assert len(t['tests'])==1 and len(t['docExamples'])==4 and len(t['docExamples'][0]['tests'])==2
assert r['complete'] and not r['diagnostics'] and r['sources'] and r['sourceSets']
for e in t['docExamples']:
 assert e['complete'] and e['status']=='ok' and e['sourceId']
 assert all(k in e for k in ['id','mode','location','effects','tests','expectedDiagnosticCodes','observedDiagnostics'])
rows=[json.loads(x) for x in run('doc four jsonl',[CLI,'test','--doc','--diagnostics=json','--allow-effects=Assert.Check,Console.Write',p]).stdout.splitlines()]
assert rows[-1]['passed']==5 and rows[-1]['failed']==0
assert rows[-2]=={'kind':'docSummary','check':1,'error':1,'ignoredBlocks':0,'run':1,'test':1}
# 後のrun例のConsole.Writeを拒否すると通常テストを含め何も実行しない。
rows=[json.loads(x) for x in run('doc all preflight',[CLI,'test','--doc','--diagnostics=json','--allow-effects=Assert.Check',p],expected=2,contains=['E0512']).stdout.splitlines()]
assert all(x['kind'] not in ['test','docExample'] for x in rows)
assert rows[-1]['kind']=='testSummary' and rows[-1]['passed']==0 and rows[-1]['failed']==0
# 実行とcheckの通常の権限指定も確認する。
main='''import Benitoite.IO.Console
function main() -> Unit uses Console.Write
 Console.writeLine("ready")
end function
'''
p=write('console.bnt',main)
run('run allowed',[CLI,'run','--allow-effects=Console.Write',p],contains=['ready'])
run('run denied',[CLI,'run','--allow-effects=',p],expected=2,contains=['E0512'],absent=['ready'])

