harness.py.text:
import json, subprocess, time, hashlib, pathlib, os, re
T=pathlib.Path(__file__).parent
R=pathlib.Path(json.loads((T/'context.json').read_text())['repo'])
CLI=R/'target/release/benitoite'
I=T/'inputs'
def write(name, text):
 p=I/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text);return p
def run(label,args,cwd=None,expected=0,contains=(),absent=()):
 start=time.monotonic(); r=subprocess.run([str(a) for a in args],cwd=str(cwd or I),capture_output=True,text=True)
 row={'label':label,'argv':[str(a) for a in args],'cwd':str(cwd or I),'exit':r.returncode,'seconds':round(time.monotonic()-start,3),'stdout':r.stdout,'stderr':r.stderr}
 with (T/'logs'/'commands.jsonl').open('a') as f:f.write(json.dumps(row,ensure_ascii=False)+'\n')
 print(label, 'exit='+str(r.returncode), (r.stdout+r.stderr)[:170].replace('\n',' | '),flush=True)
 assert r.returncode==expected,(label, r.returncode, (r.stdout+r.stderr)[:1800])
 for s in contains:assert s in r.stdout+r.stderr,(label,'missing',s,row)
 for s in absent:assert s not in r.stdout+r.stderr,(label,'unexpected',s,row)
 return r
def section(n):
 d=(R/'docs/2026-10-18-TODO-021_022_026_032_087_088_142_164_248_257_258_259_260-syntax-batch3/design.md').read_text()
 return d.split('### '+n+' ')[1].split('\n### ')[0].split('\n## ')[0]
def blocks(n):
 return re.findall(r'(?<!`)```benitoite\n(.*?)\n```(?!`)',section(n),re.S)

