from harness import *
run('version',[CLI,'--version=json'])
for v,e,c in [('0.0.9',0,''),('0.0.8',2,'E0908'),('0.0.10',2,'E0907'),('0.0.x',2,'E0905')]:
 p=write('lang-'+v+'.bnt','language "'+v+'"\nfunction main() -> Unit\n return ()\nend function\n')
 run('language '+v,[CLI,'check',p],expected=e,contains=[c])
for n,ix,name in [('15.1',0,'scope'),('15.1',2,'endpoint'),('15.2',0,'range'),('15.3',0,'regex'),('15.4',0,'monad2'),('15.5',0,'builders'),('15.7',0,'failure'),('15.10',0,'small'),('15.10',1,'higher'),('15.11',0,'property')]:
 b=blocks(n)[ix];p=write(name+'.bnt',b+'\n')
 if name=='small':
  run('small check',[CLI,'check',p]);run('small run',[CLI,'run',p])
 else:run(name+' test',[CLI,'test',p])
